contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address baseToken_,
        address nft_,
        uint128 virtualBaseTokenReserves_,
        uint128 virtualNftReserves_,
        uint56 changeFee_,
        uint16 feeRate_,
        bytes32 merkleRoot_,
        bool useStolenNftOracle_,
        bool payRoyalties_
    ) public {
        require(feeRate_ <= 5000, "feeRate too high");
        require(!c.initialized(), "already initialized");

        c.initialize(
            baseToken_,
            nft_,
            virtualBaseTokenReserves_,
            virtualNftReserves_,
            changeFee_,
            feeRate_,
            merkleRoot_,
            useStolenNftOracle_,
            payRoyalties_
        );

        assert(c.baseToken() == baseToken_);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5_000);
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted) {
            assert(c.nft() == _nft);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5_000);

        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address observedNft = c.nft();

        assert(reverted || observedNft == _nft);
    }

    receive() external payable {}
}
